import "core-js/modules/es.array.push.js";
import SavedRecords from './components/SavedRecords.vue';
import RecordForm from './components/RecordForm.vue';
export default {
  name: 'App',
  components: {
    SavedRecords,
    RecordForm
  },
  data() {
    return {
      records: JSON.parse(localStorage.getItem('accountRecords')) || [],
      editingRecord: null
    };
  },
  methods: {
    saveRecord(record) {
      if (this.editingRecord) {
        // 编辑模式：更新现有记录
        const index = this.records.findIndex(r => r.url === this.editingRecord.url && r.account === this.editingRecord.account);
        if (index !== -1) {
          this.records[index] = {
            ...record
          };
        }
        this.editingRecord = null;
      } else {
        // 新增模式：添加新记录
        const newRecord = {
          ...record,
          id: Date.now(),
          // 添加唯一ID
          timestamp: new Date().toLocaleString() // 添加时间戳
        };
        this.records.push(newRecord);
      }
      localStorage.setItem('accountRecords', JSON.stringify(this.records));
    },
    editRecord(record) {
      this.editingRecord = {
        ...record
      };
    },
    deleteRecord(index) {
      this.records.splice(index, 1);
      localStorage.setItem('accountRecords', JSON.stringify(this.records));
    },
    updateRecords(updatedRecords) {
      this.records = updatedRecords;
      localStorage.setItem('accountRecords', JSON.stringify(this.records));
    }
  },
  watch: {
    editingRecord: {
      handler(newRecord) {
        if (!newRecord) {
          // 重置表单
          this.$nextTick(() => {
            const form = document.querySelector('.record-form form');
            if (form) {
              form.reset();
            }
          });
        }
      }
    }
  }
};
